// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 100 wei);
        vm.prank(alice);
        c.addToBalance{value: 100 wei}();
        uint256 returned = c.getBalance(alice);
        assertTrue(returned == 100);
    }
}
